CREATE TABLE `custom_orders` (`id` text PRIMARY KEY NOT NULL,`reference` text NOT NULL UNIQUE,`org_type` text DEFAULT 'other' NOT NULL,`org_name` text NOT NULL,`contact_name` text NOT NULL,`contact_role` text DEFAULT '' NOT NULL,`email` text NOT NULL,`phone` text NOT NULL,`division` text DEFAULT '' NOT NULL,`district` text DEFAULT '' NOT NULL,`product` text NOT NULL,`product_other` text DEFAULT '' NOT NULL,`quantity` integer NOT NULL,`sizes` text DEFAULT '{}' NOT NULL,`colours` text DEFAULT '' NOT NULL,`design_route` text DEFAULT 'idea' NOT NULL,`design_link` text DEFAULT '' NOT NULL,`brief` text DEFAULT '' NOT NULL,`deadline` text DEFAULT '' NOT NULL,`note` text DEFAULT '' NOT NULL,`status` text DEFAULT 'new' NOT NULL,`admin_note` text DEFAULT '' NOT NULL,`version` integer DEFAULT 1 NOT NULL,`created_at` text NOT NULL,`updated_at` text NOT NULL);
